	sections = {
		{
			title = "Summary",
			text = [=[The Hall of Thanes lies in the caverns beneath {link:old-ironforge}Old Ironforge{/link}, far below {link:high-seat}the High Seat{/link}. It is a place of tombs and vaults, where the great dwarves of {link:ironforge}Ironforge{/link}'s past were laid to rest and the treasures of its kings were sealed away. For generations only its keepers walked there. Now the dead are restless, and the {link:dark-iron-dwarves}Dark Irons{/link} have broken in from below.]=],
		},
		{
			title = "Origins",
			text = [=[No chronicle records when the first thane was laid to rest in these halls. The vaults at their deepest point are called the Reliquary of Kings. Among the relics kept there was a tablet of stone from the days after the war of the three clans, when Madoran became the first Bronzebeard king of {link:ironforge}Ironforge{/link}: the treaty of peace between the Bronzebeards and the Wildhammers, which the {link:dark-iron-dwarves}Dark Irons{/link} refused to sign. Another chamber, Anvilmar's Rest, holds the tomb of a thane named {link:faldrim-anvilmar}Faldrim Anvilmar{/link}.]=],
		},
		{
			title = "The Incursion",
			text = [=[{link:earthseer-farsen}Earthseer Farsen{/link}, a Wildhammer visiting {link:dun-morogh}Dun Morogh{/link}, was the first to see the danger. Dark Iron spies had come into the land, and a map taken from their dead showed tunnels that met beneath {link:ironforge}Ironforge{/link}. The {link:dark-iron-dwarves}Dark Irons{/link} came up into the vaults in mole machines. Their looters began stripping the tombs of their heirlooms, their engineers hurled bombs, and their summoners called up fire. Stone golems walk at their side. At the same time, the spirits of the dead woke, angry and tormented, and began to haunt their own halls.]=],
		},
		{
			title = "Bosses",
			text = [=[• {b}{link:faldrim-anvilmar}Faldrim Anvilmar{/link}{/b}, a thane of old whose spirit cannot rest, consumed by an ancient grudge.
• {b}{link:magmatus}Magmatus{/link}{/b}, a creature of living fire that fights beside a Dark Iron summoner.
• {b}Plunder{/b}, an elemental that roams a hall of the vaults and hurls intruders aside.
• {b}{link:durgen-dirgehammer}Durgen Dirgehammer{/link}{/b}, the commander of the Dark Iron incursion, guarded by golems in the lower vaults.]=],
		},
		{
			title = "In the Present Day",
			text = [=[The keepers of the tombs will not go down into the hall until the dead are quiet. A {link:gnomes}gnome{/link} who claims he was patrolling the vaults wants the heirlooms carried back up, and says he will catalogue them. {link:earthseer-farsen}Earthseer Farsen{/link} asks for volunteers to go down, find the Dark Iron commander and carry his head to the king. King {link:magni-bronzebeard}Magni Bronzebeard{/link} has promised that once the invaders are gone, the breaches will be sealed and the lower halls made strong, so that no enemy can come this way again.]=],
